declare enum MetadataMergeStrategy {
    /**
     *
     * Allowed only when the operator values are equal. If not, this MUST result in a policy error.
     *
     */
    OperatorValuesEqual = 0,
    /**
     *
     * The result of merging the values of two these operators is the union of the operator values.
     *
     */
    Union = 1,
    /**
     *
     * The result of merging the values of two these operators is the intersection of the operator values. If the intersection is empty, this MUST result in a policy error.
     *
     */
    Intersection = 2,
    /**
     *
     * If a Superior has specified essential=true, then a Subordinate MUST NOT change that. If a Superior has specified essential=false, then a Subordinate is allowed to change that to essential=true. If a Superior has not specified essential, then a Subordinate can set essential to true or false. If those conditions are not met, this MUST result in a policy error.
     *
     */
    SuperiorFollowsIfTrue = 3
}

declare enum MetadataOrderOfApplication {
    First = 0,
    AfterValue = 1,
    AfterAdd = 2,
    AfterDefault = 3,
    AfterOneOf = 4,
    AfterSubsetOf = 5,
    Last = 6
}

type MetadataOperator<TKey extends string> = {
    key: TKey;
    parameterJsonValues: Array<z.ZodSchema>;
    operatorJsonValues: Array<z.ZodSchema>;
    canBeCombinedWith: Array<string>;
    orderOfApplication: MetadataOrderOfApplication;
    mergeStrategy: MetadataMergeStrategy;
};

declare const swapValidators: <T extends z.ZodRawShape>(schema: z.ZodObject<T>, newValidator: z.ZodSchema) => z.ZodObject<Record<string, typeof newValidator>>;

declare const createPolicyOperatorSchema: <TKey extends string>(operator: MetadataOperator<TKey>) => {
    /**
     * The key of the operator which is used to identify the operator
     */
    readonly key: TKey;
    /**
     * The merge strategy of the operator
     */
    readonly mergeStrategy: MetadataMergeStrategy;
    /**
     * The order of application of the operator
     */
    readonly orderOfApplication: MetadataOrderOfApplication;
    /**
     * The operator itself
     */
    readonly operator: MetadataOperator<TKey>;
    /**
     * The schema for the operator itself so for essential it is only a boolean
     */
    readonly operatorSchema: zod.ZodOptional<zod.ZodType<any, zod.ZodTypeDef, any>>;
    /**
     * The schema for the parameter the operator can be applied to so when the policy is targeting federation_entity we can check if the policy can handle that property
     */
    readonly parameterSchema: zod.ZodOptional<zod.ZodType<any, zod.ZodTypeDef, any>>;
};

